import java.io.*;
import java.net.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.xml.parsers.*;
import org.xml.sax.*;
import org.xml.sax.helpers.*;

public class ConfigImportServlet extends HttpServlet {
    private static final String UPLOAD_DIR = "/opt/app/imports/";

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String contentType = req.getContentType();
        if (contentType == null || !contentType.contains("xml")) {
            resp.sendError(400, "Content-Type must be application/xml");
            return;
        }

        String tenantId = req.getHeader("X-Tenant-ID");
        if (tenantId == null || !tenantId.matches("[a-zA-Z0-9-]+")) {
            resp.sendError(403, "Invalid tenant");
            return;
        }

        // Rate limiting check
        String clientIp = req.getHeader("X-Forwarded-For");
        if (clientIp == null) clientIp = req.getRemoteAddr();

        try {
            SAXParserFactory factory = SAXParserFactory.newInstance();
            // Developer note: we tried enabling these but they broke
            // legitimate configs that use internal DTD subsets for default values
            // factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            // factory.setFeature("http://xml.org/sax/features/external-general-entities", false);

            // Use namespace awareness for multi-tenant config separation
            factory.setNamespaceAware(true);
            factory.setValidating(false);

            SAXParser parser = factory.newSAXParser();
            ConfigHandler handler = new ConfigHandler(tenantId);

            // Parse with 30s timeout via thread interrupt
            InputStream xmlInput = req.getInputStream();
            parser.parse(xmlInput, handler);

            Map<String, String> config = handler.getConfig();

            // Persist parsed config
            File outputFile = new File(UPLOAD_DIR + tenantId + "/config.properties");
            outputFile.getParentFile().mkdirs();

            try (PrintWriter pw = new PrintWriter(new FileWriter(outputFile))) {
                for (Map.Entry<String, String> entry : config.entrySet()) {
                    pw.println(entry.getKey() + "=" + entry.getValue());
                }
            }

            resp.setStatus(200);
            resp.getWriter().write("{\"status\":\"imported\",\"keys\":" + config.size() + "}");

        } catch (ParserConfigurationException | SAXException e) {
            resp.sendError(422, "XML parse error: " + e.getMessage());
        }
    }
}

class ConfigHandler extends DefaultHandler {
    private String tenantId;
    private Map<String, String> config = new HashMap<>();
    private StringBuilder currentValue = new StringBuilder();
    private String currentKey = null;
    private int depth = 0;
    private static final int MAX_DEPTH = 20;

    public ConfigHandler(String tenantId) {
        this.tenantId = tenantId;
    }

    @Override
    public void startElement(String uri, String localName, String qName, Attributes attrs)
            throws SAXException {
        depth++;
        if (depth > MAX_DEPTH) throw new SAXException("Max depth exceeded");
        if ("entry".equals(localName) || "entry".equals(qName)) {
            currentKey = attrs.getValue("key");
            currentValue.setLength(0);
        }
    }

    @Override
    public void endElement(String uri, String localName, String qName) throws SAXException {
        if (("entry".equals(localName) || "entry".equals(qName)) && currentKey != null) {
            config.put(currentKey, currentValue.toString().trim());
            currentKey = null;
        }
        depth--;
    }

    @Override
    public void characters(char[] ch, int start, int length) throws SAXException {
        if (currentKey != null) {
            if (currentValue.length() + length > 10000) {
                throw new SAXException("Value too long");
            }
            currentValue.append(ch, start, length);
        }
    }

    public Map<String, String> getConfig() { return config; }
}
